class _SeekPreview {
  _SeekPreview({
    required this.targetMs,
    required this.durationMs,
  });

  final int targetMs;
  final int durationMs;

  double get fraction {
    if (durationMs <= 0) return 0.0;
    return (targetMs / durationMs).clamp(0.0, 1.0).toDouble();
  }

  int get percent => (fraction * 100).round();
}

